using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem Tests ---

    [TestMethod]
    public void AddItem_SingleItem_IncreasesItemCount()
    {
        _cart.AddItem("SKU-001", 2, 9.99m);

        Assert.AreEqual(2, _cart.ItemCount);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _cart.AddItem("SKU-001", 1, 5.00m);
        _cart.AddItem("SKU-001", 3, 5.00m);

        Assert.AreEqual(4, _cart.ItemCount);
    }

    [TestMethod]
    public void AddItem_MultipleDifferentSkus_TracksEachSku()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 1, 20m);

        Assert.HasCount(2, _cart.Skus);
        Assert.Contains("A", _cart.Skus);
        Assert.Contains("B", _cart.Skus);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(sku!, 1, 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_InvalidQuantity_Throws(int quantity)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", quantity, 10m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", 1, -1m));
    }

    // --- RemoveItem Tests ---

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-001", 2, 10m);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(0, _cart.ItemCount);
        Assert.DoesNotContain("SKU-001", _cart.Skus);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsInvalidOperation()
    {
        var ex = Assert.ThrowsExactly<InvalidOperationException>(() => _cart.RemoveItem("NOPE"));
        Assert.Contains("NOPE", ex.Message);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void RemoveItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.RemoveItem(sku!));
    }

    // --- CalculateTotal Tests ---

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsQuantityTimesPrice()
    {
        _cart.AddItem("SKU", 3, 10.50m);

        Assert.AreEqual(31.50m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfAll()
    {
        _cart.AddItem("A", 2, 5m);   // 10
        _cart.AddItem("B", 1, 20m);  // 20

        Assert.AreEqual(30m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemovingItem_ExcludesRemoved()
    {
        _cart.AddItem("A", 1, 100m);
        _cart.AddItem("B", 1, 50m);
        _cart.RemoveItem("A");

        Assert.AreEqual(50m, _cart.CalculateTotal());
    }

    // --- ApplyCoupon Tests ---

    [TestMethod]
    [DataRow("SAVE10", 10)]
    [DataRow("SAVE20", 20)]
    [DataRow("HALFOFF", 50)]
    public void ApplyCoupon_ValidCode_AppliesDiscount(string code, int discountPercent)
    {
        _cart.AddItem("SKU", 1, 100m);
        _cart.ApplyCoupon(code);

        var expected = 100m - (100m * discountPercent / 100m);
        Assert.AreEqual(expected, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_Works()
    {
        _cart.AddItem("SKU", 1, 200m);
        _cart.ApplyCoupon("save10");

        Assert.AreEqual(180m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsArgument()
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon("BOGUS"));
        Assert.Contains("BOGUS", ex.Message);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void ApplyCoupon_NullOrEmpty_Throws(string? code)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_AppliedTwice_UsesLatestCoupon()
    {
        _cart.AddItem("SKU", 1, 100m);
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(80m, _cart.CalculateTotal());
    }

    // --- Integration / Combination Tests ---

    [TestMethod]
    public void FullWorkflow_AddItemsApplyCouponRemoveItem_CorrectTotal()
    {
        _cart.AddItem("A", 2, 25m);  // 50
        _cart.AddItem("B", 1, 30m);  // 30
        _cart.ApplyCoupon("SAVE10");  // 10% off
        _cart.RemoveItem("B");        // leaves 50

        // 50 - 10% = 45
        Assert.AreEqual(45m, _cart.CalculateTotal());
    }
}

